def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seeds = [(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0,1)]
    # Propagate each marker through the nonzero drawing; when marked regions
    # are joined by a thin bridge, resolve ownership by shortest 4-way path.
    dist = [[None]*w for _ in range(h)]
    owner = [[None]*w for _ in range(h)]
    q = deque()
    for r,c,color in seeds:
        dist[r][c] = 0
        owner[r][c] = color
        q.append((r,c,color))
    while q:
        r,c,color = q.popleft()
        d = dist[r][c]
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            y,x = r+dr,c+dc
            if not (0 <= y < h and 0 <= x < w) or grid[y][x] == 0:
                continue
            nd = d+1
            if dist[y][x] is None or nd < dist[y][x]:
                dist[y][x] = nd
                owner[y][x] = color
                q.append((y,x,color))
    for r in range(1,h-1):
        for c in range(1,w-1):
            if grid[r][c] != 1 or owner[r][c] is None:
                continue
            if all(grid[r+dr][c+dc] != 0 for dr in (-1,0,1) for dc in (-1,0,1)):
